-- Custom invariant/projection triggers; table DDL is generated by Drizzle in 0028.
CREATE TRIGGER acc_bank_file_validate BEFORE INSERT ON acc_bank_statement_files BEGIN
  SELECT CASE WHEN
    NOT EXISTS (SELECT 1 FROM acc_accounting_years y WHERE y.company_id=NEW.company_id AND y.id=NEW.financial_year_id AND y.kind='financial')
    OR NEW.entry_count<>(SELECT coalesce(sum(json_array_length(s.value,'$.entries')),0) FROM json_each(NEW.manifest) s)
    OR NEW.statement_count<>(SELECT count(DISTINCT json_extract(s.value,'$.id')) FROM json_each(NEW.manifest) s)
    OR EXISTS (
      SELECT 1 FROM json_each(NEW.manifest) s
      WHERE json_type(s.value) IS NOT 'object'
        OR json_type(s.value,'$.id') IS NOT 'text' OR json_type(s.value,'$.financialHash') IS NOT 'text'
        OR json_extract(s.value,'$.ordinal') IS NOT CAST(s.key AS INTEGER)
        OR json_extract(s.value,'$.format') IS NOT NEW.format
        OR json_extract(s.value,'$.currency') IS NOT 'RON'
        OR json_type(s.value,'$.entries') IS NOT 'array'
        OR json_array_length(s.value,'$.entries')>2000
        OR NOT EXISTS (
          SELECT 1 FROM acc_statements b JOIN acc_accounting_years y ON y.company_id=b.company_id AND y.id=NEW.financial_year_id
          JOIN acc_treasury_accounts a ON a.company_id=b.company_id AND a.identifier=b.bank_account AND a.kind='bank' AND a.currency='RON'
          WHERE b.company_id=NEW.company_id AND b.id=json_extract(s.value,'$.statementId') AND b.evidence_id=NEW.evidence_id
            AND b.bank_account=json_extract(s.value,'$.bankAccount')
            AND upper(replace(a.identifier,' ',''))=json_extract(s.value,'$.sourceAccount')
            AND b.period_from=json_extract(s.value,'$.from') AND b.period_to=json_extract(s.value,'$.to')
            AND b.period_to BETWEEN y.date_from AND y.date_to
            AND b.period_to=json_extract(s.value,'$.closingDate') AND json_extract(s.value,'$.openingDate')<=b.period_from
            AND b.opening_bani=CAST(replace(json_extract(s.value,'$.opening'),'.','') AS INTEGER)
            AND b.closing_bani=CAST(replace(json_extract(s.value,'$.closing'),'.','') AS INTEGER)
            AND b.closing_bani=b.opening_bani+(SELECT coalesce(sum(CAST(replace(json_extract(e.value,'$.amount'),'.','') AS INTEGER)),0) FROM json_each(s.value,'$.entries') e)
            AND (SELECT count(*) FROM acc_statement_movements l WHERE l.company_id=b.company_id AND l.statement_id=b.id)=json_array_length(s.value,'$.entries')
        )
        OR EXISTS (
          SELECT 1 FROM json_each(s.value,'$.entries') e
          WHERE json_type(e.value) IS NOT 'object' OR json_extract(e.value,'$.ordinal') IS NOT CAST(e.key AS INTEGER)
            OR json_type(e.value,'$.id') IS NOT 'text' OR json_type(e.value,'$.identityBasis') IS NOT 'text'
            OR json_extract(e.value,'$.identityBasis') NOT IN ('bank_reference','statement_entry')
            OR NOT EXISTS (
              SELECT 1 FROM acc_movements m JOIN acc_statement_movements l ON l.company_id=m.company_id AND l.movement_id=m.id
              JOIN acc_accounting_years y ON y.company_id=m.company_id AND y.id=NEW.financial_year_id
              WHERE m.company_id=NEW.company_id AND m.id=json_extract(e.value,'$.movementId') AND l.statement_id=json_extract(s.value,'$.statementId')
                AND m.source_id=json_extract(e.value,'$.sourceId') AND m.bank_account=json_extract(s.value,'$.bankAccount')
                AND m.date=json_extract(e.value,'$.date') AND m.date BETWEEN y.date_from AND y.date_to
                AND m.date BETWEEN json_extract(s.value,'$.from') AND json_extract(s.value,'$.to')
                AND m.amount_bani<>0 AND m.amount_bani=CAST(replace(json_extract(e.value,'$.amount'),'.','') AS INTEGER)
            )
        )
    ) THEN RAISE(ABORT,'invalid_bank_file_manifest') END;
END;
--> statement-breakpoint
CREATE TRIGGER acc_bank_file_project AFTER INSERT ON acc_bank_statement_files BEGIN
  INSERT INTO acc_bank_statement_sources(company_id,id,file_evidence_id,statement_id,ordinal,bank_account,source_id,financial_hash,body)
  SELECT NEW.company_id,json_extract(s.value,'$.id'),NEW.evidence_id,json_extract(s.value,'$.statementId'),
    json_extract(s.value,'$.ordinal'),json_extract(s.value,'$.bankAccount'),json_extract(s.value,'$.sourceId'),
    json_extract(s.value,'$.financialHash'),json_remove(s.value,'$.entries') FROM json_each(NEW.manifest) s;
  INSERT INTO acc_bank_statement_entries(company_id,id,source_id,movement_id,ordinal,body)
  SELECT NEW.company_id,json_extract(e.value,'$.id'),json_extract(s.value,'$.id'),json_extract(e.value,'$.movementId'),
    json_extract(e.value,'$.ordinal'),e.value FROM json_each(NEW.manifest) s,json_each(s.value,'$.entries') e;
END;
--> statement-breakpoint
CREATE TRIGGER acc_bank_source_insert BEFORE INSERT ON acc_bank_statement_sources BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM acc_bank_statement_files f,json_each(f.manifest) s
    WHERE f.company_id=NEW.company_id AND f.evidence_id=NEW.file_evidence_id AND json_extract(s.value,'$.id')=NEW.id
      AND json_extract(s.value,'$.statementId')=NEW.statement_id AND json_extract(s.value,'$.ordinal')=NEW.ordinal
      AND json_extract(s.value,'$.bankAccount')=NEW.bank_account AND json_extract(s.value,'$.sourceId')=NEW.source_id
      AND json_extract(s.value,'$.financialHash')=NEW.financial_hash AND json_remove(s.value,'$.entries')=NEW.body
  ) THEN RAISE(ABORT,'invalid_bank_source') END;
END;
--> statement-breakpoint
CREATE TRIGGER acc_bank_entry_insert BEFORE INSERT ON acc_bank_statement_entries BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM acc_bank_statement_sources p JOIN acc_bank_statement_files f ON f.company_id=p.company_id AND f.evidence_id=p.file_evidence_id
    WHERE p.company_id=NEW.company_id AND p.id=NEW.source_id
      AND json_extract(NEW.body,'$.id')=NEW.id AND json_extract(NEW.body,'$.movementId')=NEW.movement_id
      AND json_extract(NEW.body,'$.ordinal')=NEW.ordinal
      AND json_extract(f.manifest,'$['||p.ordinal||'].entries['||NEW.ordinal||']')=NEW.body
  ) THEN RAISE(ABORT,'invalid_bank_entry') END;
END;
